async function stopExecution() {
    try {
        await api('/code/stop', 'POST');
        if (_workingTimerInterval) { clearInterval(_workingTimerInterval); _workingTimerInterval = null; }
        document.getElementById('workingTimer').textContent = '';
        isWorking = false;
        document.getElementById('sendBtn').disabled = false;
        showWorkingState('stopped', t('stopped_by_user'));
        setStatus('ready', t('ready'));
        addMessage('system', t('execution_stopped'));
    } catch {}
}
